import java.util.*;

class Solution {
  public int maxDepthBST(int[] order) {
    // a new value hangs under the deeper of its inserted predecessor and successor
    TreeMap<Integer, Integer> depth = new TreeMap<>();
    int best = 0;
    for (int v : order) {
      Map.Entry<Integer, Integer> lo = depth.lowerEntry(v), hi = depth.higherEntry(v);
      int d = 1 + Math.max(lo == null ? 0 : lo.getValue(), hi == null ? 0 : hi.getValue());
      depth.put(v, d);
      best = Math.max(best, d);
    }
    return best;
  }
}
